<?php
/**
 * In-dashboard feature documentation and contextual help.
 *
 * @package PublishRankSEO
 */
namespace PublishRankSEO\Admin;

defined( 'ABSPATH' ) || exit;

final class HelpDocumentationPage {
	public function register() {
		add_action( 'admin_menu', array( $this, 'menu' ), 30 );
		add_action( 'admin_enqueue_scripts', array( $this, 'assets' ) );
	}

	public function menu() {
		add_submenu_page( \PublishRankSEO\Core\Branding::MENU_SLUG, __( 'Feature Documentation', 'publishrank' ), __( 'Documentation & Help', 'publishrank' ), 'manage_options', 'publishrank-documentation', array( $this, 'page' ) );
	}

	public function assets( $hook ) {
		if ( false === strpos( (string) $hook, 'publishrank' ) ) {
			return; }
		wp_register_style( 'publishrank-inline-help', false, array(), PUBLISHRANK_SEO_VERSION );
		wp_enqueue_style( 'publishrank-inline-help' );
		wp_add_inline_style( 'publishrank-inline-help', '.pr-help-icon{display:inline-flex;align-items:center;justify-content:center;width:17px;height:17px;margin-left:5px;border:1px solid #2271b1;border-radius:50%;background:#fff;color:#2271b1;font-size:11px;font-weight:700;line-height:1;cursor:help;vertical-align:middle}.pr-help-pop{display:none;position:absolute;z-index:10000;max-width:300px;padding:10px 12px;border:1px solid #c3c4c7;border-radius:6px;background:#fff;color:#1d2327;box-shadow:0 3px 12px #0002;font-size:12px;font-weight:400;line-height:1.5}.pr-help-icon:focus+.pr-help-pop,.pr-help-icon:hover+.pr-help-pop{display:block}.pr-doc-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px;margin-top:20px}.pr-doc-card{padding:18px;border:1px solid #dcdcde;border-radius:8px;background:#fff}.pr-doc-card h2{margin-top:0}.pr-doc-card p{font-size:13px;line-height:1.65}.pr-doc-card code{overflow-wrap:anywhere}.pr-doc-note{padding:12px 15px;border-left:4px solid #2271b1;background:#fff;margin:16px 0}' );
		wp_register_script( 'publishrank-inline-help', '', array(), PUBLISHRANK_SEO_VERSION, true );
		wp_enqueue_script( 'publishrank-inline-help' );
		$map = array(
			'SEO title'        => 'The title search engines may show for this page. A custom value takes priority over the generated fallback.',
			'Meta description' => 'A concise summary for search snippets and social previews. Leave blank to let PublishRank derive a fallback from the content.',
			'Canonical URL'    => 'The preferred URL for this content. Use only when you intentionally need to consolidate duplicate or alternate URLs.',
			'Robots'           => 'Controls whether search engines may index or follow links on eligible pages. Avoid noindex on pages you want searchable.',
			'News sitemap'     => 'Lists recently published eligible news articles for discovery. Inclusion does not guarantee Google News placement or indexing.',
			'Image sitemap'    => 'Adds discoverable image URLs associated with eligible public content.',
			'Video sitemap'    => 'Provides metadata for eligible embedded or hosted videos when the required video details are available.',
			'Schema'           => 'Structured data describing your organization, articles, authors, breadcrumbs and related entities. Validate the rendered output after theme changes.',
			'Breadcrumbs'      => 'A hierarchical navigation trail. Check your theme before enabling visible output to avoid duplicate breadcrumbs.',
			'Redirect'         => 'Sends visitors and crawlers from an old URL to a new destination or returns a selected gone status. Check for loops before saving.',
			'IndexNow'         => 'Notifies participating search engines about URL changes. It does not guarantee indexing and is not a Google indexing API.',
			'Publisher'        => 'Your publication identity, logo, locale and social profiles used by relevant metadata and structured data.',
			'Cache'            => 'Clears or refreshes generated SEO/sitemap data. Site, plugin, CDN and host caches may also need to be purged.',
				'404'              => 'Records a privacy-conscious, bounded history of normalized not-found paths. It groups browser, mobile and crawler hits, removes query strings from referrers, ignores common asset and infrastructure probes, applies rate limiting and a short write lock, and retains at most 500 entries for 90 days.',
			'Import'           => 'Loads supported PublishRank settings. Review imported values before applying them; secrets may be deliberately excluded.',
			'Export'           => 'Downloads supported configuration for backup or migration. Keep exported files private because they may contain site configuration.',
			'Keyphrase'        => 'An editorial focus phrase used by content analysis. It is a writing aid, not a ranking guarantee.',
			'Schema type'      => 'Selects the structured-data type that best represents the content. Do not mark up content that is not actually present.',
		);
		wp_add_inline_script( 'publishrank-inline-help', '(()=>{const help=' . wp_json_encode( $map ) . ';const add=(el,msg)=>{if(el.dataset.prHelpAdded)return;el.dataset.prHelpAdded="1";const b=document.createElement("button");b.type="button";b.className="pr-help-icon";b.textContent="i";b.setAttribute("aria-label","Help: "+msg);b.title=msg;b.style.position="relative";const pop=document.createElement("span");pop.className="pr-help-pop";pop.textContent=msg;el.appendChild(b);el.appendChild(pop)};document.querySelectorAll(".wrap label, .wrap h2, .wrap h3, .wrap legend, .wrap th").forEach(el=>{const t=(el.innerText||el.textContent||"").replace(/\\s+/g," ").trim();for(const [k,v] of Object.entries(help)){if(t.length<100&&t.toLowerCase().includes(k.toLowerCase())){add(el,v);break}}});})();' );
	}

	public function page() {
		if ( ! current_user_can( 'manage_options' ) ) {
			return; }
		echo '<div class="wrap"><h1>' . esc_html__( 'PublishRank — Feature Documentation', 'publishrank' ) . '</h1><p>' . esc_html__( 'A practical guide to the controls available in PublishRank. Look for the blue “i” icons beside supported settings for quick explanations.', 'publishrank' ) . '</p>';
		echo '<p class="description">' . esc_html( sprintf( /* translators: %s: PublishRank version number. */ __( 'Documentation for PublishRank version %s.', 'publishrank' ), \PublishRankSEO\Core\Branding::version() ) ) . '</p>';
			echo '<div class="pr-doc-note"><strong>' . esc_html__( 'Important:', 'publishrank' ) . '</strong> ' . esc_html__( 'Custom values generally take priority over automatic fallbacks. SEO output can be affected by themes, caching, multilingual plugins and other SEO plugins. Avoid duplicate metadata providers.', 'publishrank' ) . '</div><div class="pr-doc-grid">';
			$sections = array(
				__( 'Features provided through version 2.9.110', 'publishrank' ) => __( 'This versioned inventory covers every dashboard feature card and Technical Health check: Search & discovery includes Schema studio, Sitemap health, IndexNow, Search Console, Search engines, Google Preferred Sources, Robots.txt, Crawl optimization, Breadcrumbs, Site verification, AI & llms.txt and Schema Aggregator. Content & publishing includes SEO score, SEO Overrides, Google Discover image, Author expertise, Local SEO, Image optimizer, Publisher toolkit, Newsroom, Planning board, Newsroom calendar, Newsroom activity, My notifications, Newsroom configuration, Newsroom roles, Internal links and Link intelligence. Measure & maintain includes Publisher analytics, Insights, Redirects, 404 monitor, Traffic Guard, WP Hide Login, Configuration history and Diagnostics. Settings & help includes Setup wizard, Settings, Titles & Meta, Import / Export and Documentation & help. Technical Health checks include SEO plugin conflicts, Search engine visibility, Pretty permalinks, HTTPS, News sitemap, Structured data coverage, Publisher logo, Default social image, Robots.txt and JNews compatibility. Some features are optional or permission-gated and external integrations require their own configuration; this inventory describes what the package provides, not a guarantee that every optional service is active on every site.', 'publishrank' ),
				__( 'Titles, descriptions & canonical URLs', 'publishrank' ) => __( 'PublishRank generates title and description fallbacks from WordPress content and templates. A custom title or description should be used when an editor needs a specific search snippet. Canonical URLs identify the preferred public URL; do not point them at unrelated pages.', 'publishrank' ),
			__( 'Title & description variables', 'publishrank' ) => __( 'Dynamic variables work in per-post SEO titles, meta descriptions, social titles, social descriptions and the homepage title and description. Use the “Insert variable” list under each field; it shows every supported variable grouped by Site, Content, Author, Taxonomy, Dates and SEO, with what each returns and what happens when it is empty. Typed tokens look like %%title%% and %%sitename%%; %%sep%% is your configured title separator, %%page%% adds “Page 2” on later pages and %%permalink%% is the canonical URL. The older %focus_keyword% form also works. Variables are replaced once, unknown variables are dropped, and a separator left dangling by an empty value is removed. Results are plain text; they are escaped when printed.', 'publishrank' ),
			__( 'Output controls & what PublishRank can override', 'publishrank' ) => __( 'Settings > Output controls and Breadcrumbs switch PublishRank metadata, the JSON-LD graph, the Organization/WebSite entities, the visible breadcrumb trail and BreadcrumbList data on or off independently; all are on for new installs and your saved choices are kept on upgrade. Changes to your publication identity apply to every page automatically. PublishRank controls only its own head metadata, JSON-LD and breadcrumb trail: a logo, site title, breadcrumb trail or meta tags that your theme or another plugin hard-codes belong to that theme or plugin. If your theme prints its own breadcrumbs choose "Structured data only"; if it prints a second title or description, disable that in the theme. Pages cached by a caching plugin or CDN need a purge after a change (PublishRank fires the publishrank_seo_output_settings_changed action for cache plugins).', 'publishrank' ),
			__( 'Breadcrumb separators', 'publishrank' ) => __( 'Pick a preset (arrows, angles, slashes and lines, dots, dashes, symbols, spaced variants, a space, a non-breaking space, or none) or type your own up to 10 characters. The separator is plain text, so HTML is not allowed; leading and trailing spaces are kept. It is visual only and never appears in BreadcrumbList structured data.', 'publishrank' ),
			__( 'XML, News, image & video sitemaps', 'publishrank' ) => __( 'The sitemap index links to the enabled sitemap types. News sitemaps focus on eligible recent articles; image and video sitemaps help describe media attached to eligible content. Check Sitemap Health after changing permalink, sitemap or cache settings. A sitemap is a discovery hint, not an indexing guarantee.', 'publishrank' ),
			__( 'Schema & publisher identity', 'publishrank' ) => __( 'Organization, NewsArticle, author, breadcrumb and media structured data help describe the publication and its content. Complete the publisher identity and logo fields accurately. Do not add custom JSON-LD that duplicates or contradicts generated entities.', 'publishrank' ),
			__( 'Robots, archives & indexing controls', 'publishrank' ) => __( 'Robots settings influence crawling and indexing signals. Use noindex carefully, especially on article pages and category archives. robots.txt rules are not a substitute for access control and do not guarantee removal from search results.', 'publishrank' ),
				__( 'Redirects & 404 monitoring', 'publishrank' ) => __( 'Use permanent redirects for durable URL moves and temporary redirects when the move is temporary. Test the destination and avoid redirect loops/chains. The 404 Monitor is opt-in and records normalized GET/HEAD 404 paths only; admin, AJAX, cron, REST, non-HTML asset and common infrastructure-probe requests are excluded. Hits are aggregated by browser, mobile or crawler category without IP addresses, cookies, request bodies or full query strings. Administrators can search, filter, sort, dismiss, clear and create validated same-site redirects from the monitor. Its 90-day, 500-entry rolling limit, rate limiting and write lock make it a bounded diagnostic aid rather than a complete access log, analytics system or WAF.', 'publishrank' ),
			__( 'IndexNow', 'publishrank' )             => __( 'IndexNow can notify supported participating search engines about URL changes after you enable it and configure its verification key. Notifications do not guarantee indexing, and Google does not use IndexNow.', 'publishrank' ),
			__( 'Baidu URL submission', 'publishrank' ) => __( 'Baidu requires a verified site and its current site-specific ordinary-inclusion endpoint. PublishRank stores that HTTPS endpoint encrypted, limits requests to the same host and batches up to 2,000 URLs. Baidu quota and eligibility vary; acceptance is not an indexing guarantee. Baidu dashboard analytics are not exposed through a documented public read API.', 'publishrank' ),
			__( 'Editorial SEO intelligence', 'publishrank' ) => __( 'Article analysis reviews signals such as headline, keyphrase, description, structure, readability, media and links. Treat scores and suggestions as editorial guidance, not a promise of ranking performance. Always prioritize accuracy and reader value.', 'publishrank' ),
			__( 'Images, media & performance', 'publishrank' ) => __( 'Image optimization settings control supported image-processing behavior. Keep originals or backups according to your workflow, test output with your theme and CDN, and verify that image dimensions and quality remain suitable for publishing.', 'publishrank' ),
			__( 'Diagnostics & compatibility', 'publishrank' ) => __( 'Run diagnostics after installation or major configuration changes. Review conflicts with themes and other SEO plugins, then inspect the live page source and sitemap responses. Disable overlapping SEO output in other plugins only after confirming which plugin owns each output.', 'publishrank' ),
			__( 'Settings import/export & configuration history', 'publishrank' ) => __( 'Use exports for controlled migration and backups. Review imported settings before relying on them, and protect exported files. Configuration history can help identify changes; it is not a substitute for a full database backup.', 'publishrank' ),
			__( 'Google Search Console & local analytics', 'publishrank' ) => __( 'The optional Search Console connection uses Google OAuth webmasters.readonly, requires a Google Cloud project with the Search Console API enabled, and stores tokens encrypted at rest. Refreshes are administrator-initiated; data is aggregated and delayed. Local Publisher Analytics is separate and does not track visitors. Never paste OAuth client secrets or tokens into public support requests.', 'publishrank' ),
			__( 'Admin menu, toolbar & the PublishRank mark', 'publishrank' ) => __( 'The PublishRank mark is the only logo used by the plugin: in the admin sidebar, the WordPress toolbar, the PublishRank screens, the setup wizard and the sitemap view. The sidebar groups tools into expandable sections (select a group heading to collapse or expand it, or use the keyboard). The dropdown uses the native WordPress menu background and text colours, so it follows whichever admin colour scheme you choose. The toolbar entry offers shortcuts to the Dashboard, Newsroom, Titles & Meta, Settings, Setup Wizard and this documentation.', 'publishrank' ),
			__( 'Sitemap index browser view', 'publishrank' ) => __( 'Open your sitemap index in a browser to see a readable overview: totals for files, content types and URLs, a content showcase bar that shows each type\'s share, and one card per content type with its files, URL counts and last-modified times. Child sitemaps show URL tables with filtering, paging and quick checks (URL limit, last-modified dates, HTTPS and news data). Search engines never use this view; they read the plain XML. Use View raw XML to see exactly what crawlers receive. Very large indexes skip per-file URL counts to stay fast.', 'publishrank' ),
			__( 'Live blogs, Newsroom & news workflow', 'publishrank' ) => __( 'Choose Live Blog Post in the Schema box and add timestamped updates to mark a live blog; ordinary posts are never marked up as live blogs automatically. The built-in Newsroom handles story pitches, assignments, workflow stages, a planning board, a calendar and private notes. These are editorial aids and do not change what is published until you publish.', 'publishrank' ),
			__( 'Versions, updates & support', 'publishrank' ) => __( 'The plugin version appears on every PublishRank screen header, in the sitemap view footer, in the plugin header and in the readme stable tag; all of them always show the same number. After updating, clear your site, plugin, CDN and browser caches so you see the current admin styles and sitemap stylesheet. If something looks wrong, run Diagnostics and Sitemap Health first, then check for conflicts with other SEO plugins.', 'publishrank' ),
			__( 'Pre-publication story preflight', 'publishrank' ) => __( 'The Publisher Toolkit Pre-publication Preflight tab lists draft, pending and scheduled stories the current editor can edit. It reuses the local SEO checklist and site timezone for schedule times. Suggestions are advisory: the queue is read-only and never blocks publication.', 'publishrank' ),
			__( 'Troubleshooting', 'publishrank' ) => __( 'Sitemap shows a blank page or plain text: open Settings > Permalinks and select Save to refresh rewrite rules, then reload. Sitemap view looks unstyled: purge page, CDN and browser caches, then reload. The stylesheet is generated by WordPress at /publishrank-sitemap.xsl, so a caching layer that rewrites or blocks that URL can break it. Menu or toolbar icon missing: purge caches and confirm that assets/images/publishrank-brand-mark.png exists and is readable. Duplicate titles or schema: leave only one plugin responsible for each output. News sitemap empty: it only lists eligible recent articles, and an empty sitemap is valid.', 'publishrank' ),
		);
		foreach ( $sections as $title => $description ) {
			echo '<section class="pr-doc-card"><h2>' . esc_html( $title ) . '</h2><p>' . esc_html( $description ) . '</p></section>'; }
		echo '</div><p class="description">' . esc_html__( 'Official website, online documentation and support:', 'publishrank' ) . ' <a href="' . esc_url( \PublishRankSEO\Core\Branding::website_url() ) . '" target="_blank" rel="noopener noreferrer">' . esc_html__( 'PublishRank Official Website', 'publishrank' ) . '</a></p></div>';
	}
}
